using System;using System.Reflection;using System.Windows.Forms;using Briefly;
class UpdateBannerTest{
 [STAThread]static int Main(){var flags=BindingFlags.Instance|BindingFlags.NonPublic;using(var f=new MainForm(false)){f.Show();var banner=(Panel)typeof(MainForm).GetField("pnlUpdateBanner",flags).GetValue(f);var shell=(TableLayoutPanel)typeof(MainForm).GetField("referenceShell",flags).GetValue(f);var body=(Panel)typeof(MainForm).GetField("pnlBody",flags).GetValue(f);banner.Visible=true;Application.DoEvents();shell.PerformLayout();if(shell.GetRow(banner)!=0||shell.GetRow(body)!=1||shell.RowStyles[0].Height<44||body.Top<banner.Bottom)throw new Exception("Update banner is hidden behind the new shell");var button=(Button)typeof(MainForm).GetField("btnUpdateLink",flags).GetValue(f);if(button.Text!="Download update"||!button.Visible)throw new Exception("Update action missing");f.Close();}Console.WriteLine("Real native update banner occupies its own visible row and has a Download update action.");return 0;}
}
